theme.template:
{{$radio = round( ($slider->img_h/$slider->img_w), 2 ) * 100;}}
{{$titleHeight = $slider->truncate > 0 ? (35 * $slider->truncate) . 'px' : 'auto';}}
<div id="Fcontent_{$slider->id}" class="{{if $conf['fcontent_use_wrapper']}}ipsBox{{endif}} {{if $slider->hideinmobile == 1}}ipsResponsive_hidePhone{{endif}}">
	{{if $slider->showname == 1}}
		{{if $conf['fcontent_use_wrapper']}}
			<h3 class="ipsWidget_title ipsType_reset">
				{$slider->title}
			</h3>		
		{{else}}
			<div class="ipsPageHeader ipsClearfix sliderTitle">
				<h1 class="ipsType_pageTitle">{$slider->title}</h1>
			</div>
		{{endif}}
	{{endif}}
	<div class="{{if $conf['fcontent_use_wrapper']}}ipsPad{{endif}}">
		<div id='fcGridWrapper_{$slider->id}' class="fcGridWrapper nolinks norewrite">
			<div class='ipsGrid' data-ipsGrid data-ipsGrid-minItemSize='200' data-ipsGrid-equalHeights='row'>
				{{foreach $data as $row}}
					<div class='ipsGrid_span3 ipsSpacer_half ipsSpacer_bottom ipsBox'>
						<li class="fcitem" {{if $row['id']>0}}id="fcc_{$row['id']}"{{endif}}>
							{{if $slider->nolink != 1}}
								{{if $slider->viewlinkin == '3' && $slider->method != 'noauto' && $slider->method != 'gallery'}}
									<a href="#" data-ipsDialog data-ipsDialog-forceReload data-ipsDialog-url="{url="app=featuredcontent&module=slider&controller=view&do=popup&id={$slider->id}&item={$row['id']}"}" data-ipsDialog-size='medium' title="{$row['title']}">
								{{else}}
									<a href="{$row['url']}" title="{$row['title']}" {{if $slider->viewlinkin == 'page' || $row['newtab'] == 1}}target=_blank{{endif}}>
								{{endif}}
							{{endif}}

									<div class="fc_img_container" style="background-image:url('{$row['image']}'); height: 100%; max-height:{$slider->itemHeight}; width:100%; padding-bottom: {$radio}%;"></div>

									{{if $slider->showtitle == 1 && $row['title']}}
										<div class="{{if $slider->title_pos == 'inside'}}bx-caption{{else}}bx-caption2{{endif}}">
											<span data-ipsTruncate data-ipsTruncate-type="remove" data-ipsTruncate-size="{$slider->truncate} lines">
												{$row['title']}
											</span>
										</div>
									{{endif}}

							{{if $slider->nolink != 1}}
								</a>
							{{endif}}

							{{if $slider->showtitle == 1 && $row['title'] && $row['author'] && $slider->title_pos == 'below'}}
								<div class='fcAuthor ipsType_reset ipsType_medium ipsType_light ipsType_blendLinks'>
									{lang="byline_nodate" htmlsprintf="$row['author']->link()"} {datetime="$row['date']"}
								</div>
							{{endif}}

							{{if $slider->method == 'noauto' AND ( $slider->can('manage') OR ( $row['moderators'] AND \in_array( member.member_id, explode( ",", $row['moderators'] ) ) ) )}}
								<div class="modbutton">
									<a href='#' data-ipsdialog='' data-ipsDialog-url="{url="app=featuredcontent&module=slider&controller=view&do=manageslider&id={$slider->id}&item={$row['id']}"}" data-ipsdialog-size='narrow' data-ipsdialog-title='{lang="fcs_edit"}' data-ipsdialog-forcereload='true'>
										<i class="fa fa-pencil"></i>
									</a>
								</div>
							{{endif}}
						</li>
					</div>
				{{endforeach}}
			</div>
			{{if $slider->method == 'noauto' AND $slider->can('manage')}}
				<div class="addbutton">
					<a href="{url="app=featuredcontent&module=slider&controller=view&id={$slider->id}"}" title='{lang="fcontent_manageslider"}'><i class="fa fa-cog"></i></a>
				</div>
			{{endif}}
		</div>
	</div>
</div>

{{$titleHeight = $slider->truncate > 0 ? (35 * $slider->truncate) . 'px' : 'auto';}}
<div id="Fcontent_{$slider->id}" class="{{if $conf['fcontent_use_wrapper']}}ipsBox{{endif}} {{if $slider->hideinmobile == 1}}ipsResponsive_hidePhone{{endif}}">
	{{if $slider->showname == 1}}
		{{if $conf['fcontent_use_wrapper']}}
			<h3 class="ipsWidget_title ipsType_reset">
				{$slider->title}
			</h3>		
		{{else}}
			<div class="ipsPageHeader ipsClearfix sliderTitle">
				<h1 class="ipsType_pageTitle">{$slider->title}</h1>
			</div>
		{{endif}}
	{{endif}}
	<div class="{{if $conf['fcontent_use_wrapper']}}ipsPad{{endif}}">
		<div id='sliderWrapper_{$slider->id}' class="sliderWrapper {{if $slider->ticker && $slider->style != 'vertical'}}fcTicker{{endif}} nolinks norewrite">
			<ul class='slider_{$slider->id}' {{if $slider->style != 'horizontal'}}style='margin-left: -40px;'{{endif}}>
				{{foreach $data as $row}}
					<li class="fcitem {{if $slider->title_pos == 'below'}}ipsBox{{endif}}" {{if $row['id']>0}}id="fcc_{$row['id']}"{{endif}} style='{{if $slider->ticker && $slider->margin>0}}margin-right:{$slider->margin}px;{{endif}}{{if $slider->title_pos == 'below'}}padding-bottom: {$slider->titleHeight};{{endif}}'>
						{{if $slider->nolink != 1}}
							{{if $slider->viewlinkin == '3' && $slider->method != 'noauto' && $slider->method != 'gallery'}}
								<a href="#" data-ipsDialog data-ipsDialog-forceReload data-ipsDialog-url="{url="app=featuredcontent&module=slider&controller=view&do=popup&id={$slider->id}&item={$row['id']}"}" data-ipsDialog-size='medium' title="{$row['title']}">
							{{else}}
								<a href="{$row['url']}" title="{$row['title']}" {{if $slider->viewlinkin == 'page' || $row['newtab'] == 1}}target=_blank{{endif}}>
							{{endif}}
						{{endif}}

								<div class="fc_img_container" style="background-image:url('{$row['image']}'); {{if $slider->ticker}}height: {$slider->itemHeight}; width:{$slider->itemWidth};{{else}}height: 100%; max-height:{$slider->itemHeight}; width:100%;{{endif}}padding-bottom: {$slider->titleHeight};"></div>

								{{if $slider->showtitle == 1 && $row['title']}}
									<div class="{{if $slider->title_pos == 'inside'}}bx-caption{{else}}bx-caption2{{endif}}">
										<span data-ipsTruncate data-ipsTruncate-type="remove" data-ipsTruncate-size="{$slider->truncate} lines">
											{$row['title']}
										</span>
									</div>
								{{endif}}

						{{if $slider->nolink != 1}}
							</a>
						{{endif}}

						{{if $slider->showtitle == 1 && $row['title'] && $slider->title_pos == 'below'}}
							<div class='fcAuthor ipsType_reset ipsType_medium ipsType_light ipsType_blendLinks'>
								{lang="byline_nodate" htmlsprintf="$row['author']->link()"} {datetime="$row['date']"}
							</div>
						{{endif}}

						{{if $slider->method == 'noauto' AND ( $slider->can('manage') OR ( $row['moderators'] AND \in_array( member.member_id, explode( ",", $row['moderators'] ) ) ) )}}
							<div class="modbutton">
								<a href='#' data-ipsdialog='' data-ipsDialog-url="{url="app=featuredcontent&module=slider&controller=view&do=manageslider&id={$slider->id}&item={$row['id']}"}" data-ipsdialog-size='narrow' data-ipsdialog-title='{lang="fcs_edit"}' data-ipsdialog-forcereload='true'>
									<i class="fa fa-pencil"></i>
								</a>
							</div>
						{{endif}}
					</li>	
				{{endforeach}}
			</ul>
			{{if $slider->method == 'noauto' AND $slider->can('manage')}}
				<div class="addbutton">
					<a href="{url="app=featuredcontent&module=slider&controller=view&id={$slider->id}"}" title='{lang="fcontent_manageslider"}'><i class="fa fa-cog"></i></a>
				</div>
			{{endif}}
		</div>
	</div>
</div>
{{\IPS\Output::i()->endBodyCode .= \IPS\Theme::i()->getTemplate( 'embed', 'featuredcontent', 'front' )->config( $slider );}}

{{if \IPS\featuredcontent\Slider::canOnAny('manage')}}
	{{$sliders = \IPS\featuredcontent\Slider::roots();}}
	{{if !empty( $sliders )}}
		<li>
			<a href='#elFcontent_menu' id='elFcontent' class='ipsButton ipsButton_link ipsButton_medium ipsButton_fullWidth' data-ipsMenu>{lang="fcontent_addfrom"} <i class='fa fa-caret-down'></i></a>
			<ul id='elFcontent_menu' class='ipsMenu ipsMenu_auto ipsHide'>
				{{foreach $sliders as $slider}}
					{{if \IPS\featuredcontent\Slider::can('manage') AND $slider->enabled == 1 AND $slider->method == 'noauto'}}
						<li class='ipsMenu_item'>
							<a href='#' data-ipsdialog='' data-ipsDialog-url="{url="app=featuredcontent&module=slider&controller=view&do=add&id={$slider->id}&from={$from}&contentID={$contentID}"}" data-ipsdialog-size='narrow' data-ipsdialog-title='{lang="fcs_edit"}' data-ipsdialog-forcereload='true'>
								{$slider->title}
							</a>
						</li>
					{{endif}}
				{{endforeach}}
			</ul>
		</li>
	{{endif}}
{{endif}}

			
{{if ( $slider->enabled != 1 || \count( $slider->getContents() ) == 0 )}}
	{template="noContent" app="featuredcontent" group="embed" location="front" params="$slider"}
{{else}}
	<ul class='ipsList_reset'>
		{{if $slider->style == 'grid'}}
			{template="showGrid" app="featuredcontent" group="embed" location="front" params="$slider, $slider->getContents(), $conf"}
		{{else}}
			{template="showSlider" app="featuredcontent" group="embed" location="front" params="$slider, $slider->getContents(), $conf"}
		{{endif}}
	</ul>
{{endif}}

theme.css:
/** RESET AND LAYOUT
===================================*/
.sliderWrapper {
	position: relative; 
	opacity: 0; 
	height: 0px;
}
.sliderContainer {
	position: relative; padding: 0; margin: 0;
}
.sliderTitle {
	padding-bottom: 5px;
}


.fcGridWrapper,
.fcGridWrapper .fcitem {
	position: relative;
}

.fcWrapper {
	position: relative;
	margin: 0 auto 15px;
	padding: 0;
	*zoom: 1;
	/* direction:ltr; */
}

.fcWrapper img {
	max-width: 100%;
	max-height: 100%;
	display: block;
	margin: 0 auto;
}

.editbutton {
  position: absolute;
  top: 3px; left: 3px;
  color: #fff;
  background: #000;
  padding: 3px 4px 3px 4px;
  border-radius: 3px;
  opacity: 0.3;
}
.editbutton a {
  color: #fff; text-decoration:none;
}
.editbutton:hover{
  opacity: 1;
}

.addbutton {
  position: absolute;
  top: 3px; right: 3px;
  color: #fff;
  background: #000;
  padding: 3px 4px 3px 4px;
  border-radius: 3px;
  opacity: 0.3;
}
.addbutton a {
  color: #fff; text-decoration:none;
}
.addbutton:hover{
  opacity: 1;
}

.modbutton {
  position: absolute;
  top: 3px; left: 3px;
  color: #fff;
  background: #000;
  padding: 3px 5px 3px 5px;
  border-radius: 3px;
  opacity: 0.3;	
}
.modbutton a {
  color: #fff; text-decoration:none;
}
.modbutton:hover{
  opacity: 1;
}
/** THEME
===================================*/

.fcWrapper .bx-viewport {
	/*-moz-box-shadow: 0 0 5px #ccc;
	-webkit-box-shadow: 0 0 5px #ccc;
	box-shadow: 0 0 5px #ccc;
	border: 2px solid #fff;*/
	left: 0px;

	/*fix other elements on the page moving (on Chrome)*/
	-webkit-transform: translatez(0);
	-moz-transform: translatez(0);
    	-ms-transform: translatez(0);
    	-o-transform: translatez(0);
    	transform: translatez(0);
}

.fcWrapper .bx-pager,
.fcWrapper .bx-controls-auto {
	position: absolute;
	bottom: -30px;
	width: 100%;
}

@media screen and (max-width: 767px) {
	.fcWrapper .bx-pager,
	.fcWrapper .bx-controls-auto {
		display: none;
	}	
}

/* LOADER */
.fcWrapper .bx-loading {
	min-height: 50px;
	background: url({resource="bx_loader.gif" app="featuredcontent" location="front"}) center center no-repeat #fff;
	height: 100%;
	width: 100%;
	position: absolute;
	top: 0;
	left: 0;
	z-index: 2000;
}

/* PAGER */

.fcWrapper .bx-pager {
	text-align: center;
	font-size: .85em;
	font-family: Arial;
	font-weight: bold;
	color: #666;
	padding-top: 20px;
}

.fcWrapper .bx-pager .bx-pager-item,
.fcWrapper .bx-controls-auto .bx-controls-auto-item {
	display: inline-block;
	*zoom: 1;
	*display: inline;
}

.fcWrapper .bx-pager.bx-default-pager a {
	background: #666;
	text-indent: -9999px;
	display: block;
	width: 10px;
	height: 10px;
	margin: 0 5px;
	outline: 0;
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
	border-radius: 5px;
}

.fcWrapper .bx-pager.bx-default-pager a:hover,
.fcWrapper .bx-pager.bx-default-pager a.active {
	background: #000;
}

/* DIRECTION CONTROLS (NEXT / PREV) */
.fcWrapper .bx-prev {
	left: 10px;
	background: url({resource="controls.png" app="featuredcontent" location="front"}) no-repeat 0 -32px;
}

.fcWrapper .bx-next {
	right: 10px;
	background: url({resource="controls.png" app="featuredcontent" location="front"}) no-repeat -43px -32px;
}

.fcWrapper .bx-prev:hover {
	background-position: 0 0;
}

.fcWrapper .bx-next:hover {
	background-position: -43px 0;
}

.fcWrapper .bx-controls-direction a {
	position: absolute;
	top: 50%;
	margin-top: -16px;
	outline: 0;
	width: 32px;
	height: 32px;
	text-indent: -9999px;
	z-index: 99 !important;
}

.fcWrapper .bx-controls-direction a.disabled {
	display: none;
}

/* AUTO CONTROLS (START / STOP) */

.fcWrapper .bx-controls-auto {
	text-align: center;
}

.fcWrapper .bx-controls-auto .bx-start {
	display: block;
	text-indent: -9999px;
	width: 10px;
	height: 11px;
	outline: 0;
	background: url({resource="controls.png" app="featuredcontent" location="front"}) -86px -11px no-repeat;
	margin: 0 3px;
}

.fcWrapper .bx-controls-auto .bx-start:hover,
.fcWrapper .bx-controls-auto .bx-start.active {
	background-position: -86px 0;
}

.fcWrapper .bx-controls-auto .bx-stop {
	display: block;
	text-indent: -9999px;
	width: 9px;
	height: 11px;
	outline: 0;
	background: url({resource="controls.png" app="featuredcontent" location="front"}) -86px -44px no-repeat;
	margin: 0 3px;
}

.fcWrapper .bx-controls-auto .bx-stop:hover,
.fcWrapper .bx-controls-auto .bx-stop.active {
	background-position: -86px -33px;
}

/* PAGER WITH AUTO-CONTROLS HYBRID LAYOUT */

.fcWrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-pager {
	text-align: left;
	width: 80%;
}

.fcWrapper .bx-controls.bx-has-controls-auto.bx-has-pager .bx-controls-auto {
	right: 0;
	width: 35px;
}

/* IMAGE CAPTIONS */
.fcGridWrapper .bx-caption,
.fcWrapper .bx-caption {
	position: absolute;
	bottom: 0;
	left: 0;
	background: #666\9;
	background: rgba(0,0,0,0.5);
	width: 100%;
}

.fcGridWrapper .bx-caption span,
.fcWrapper .bx-caption span {
	color: #fff;
	display: block;
	font-size: 13px;
	line-height: 18px;
	padding: 8px 8px 9px 8px;
}

/* CUSTOMIZATION INTERFACE */
.fc_itemWrap {
	position: relative;
}

.fc_itemWrap span {
	position: absolute;
	bottom: 0;
	left: 0;
	background: #666\9;
	background: rgba(80, 80, 80, 0.75);
	width: 100%;
	color: #fff;
	font-size: .85em;
	padding: 6px 6px 7px 6px;
}

.fc_mana { 
	position: absolute;
	background: #5E5E5E;
	border-radius: 3px;
	z-index: 1;
	top: 0;
	right: 0;
	color: #fff;		
}	
.fc_mana a { color: #fff; }

	.fc_mana p {
		display: block;
		padding: 3px 6px 3px 6px;
		background: #000;
		margin: 1px;
	}
	.fc_mana p:hover {
		background: #404040;
	}

.fcTicker {
  overflow: hidden;
  float: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  -o-user-select: none;
  user-select: none;
}


.fcTicker li {
	float: left;
	list-style: none;
	position: relative;
}

.fcTicker li .bx-caption {
	position: absolute;
	bottom: 0;
	left: 0;
	background: #666\9;
	background: rgba(0,0,0,0.5);
	width: 100%;
}

.fcTicker li .bx-caption span {
	color: #fff;
	font-family: Arial;
	display: block;
	font-size: .85em;
	padding: 8px 8px 9px 8px;
}

.fcTicker li .bx-caption2 {
	position: absolute;
	bottom: 30px;
	left: 0;
	width: 100%;
}

.fcTicker li .bx-caption2 span {
	color: inherit;
	display: block;
	font-size: 13px;
	padding: 8px 8px 0px 8px !important;
}

.fcTicker li .fcAuthor {
	position: absolute;
	bottom: 10px;
	left: 0;
	width: 100%;
	padding: 3px 8px 0px 8px !important;
}


/* Fix border and padding in widget (IPS 4.2) */
.ipsWidget.ipsWidget_horizontal.ipsBox[data-blockid^="app_featuredcontent"] {
	border: 0px solid #e0e0e0 !important;
	box-shadow: 0px 0px 0px rgba(0,0,0,0) !important;
	background: transparent !important;
	padding-bottom: 10px !important;
}
.ipsWidget.ipsWidget_vertical.ipsBox[data-blockid^="app_featuredcontent"] {
	border: 0px !important;
	box-shadow: 0px 0px 0px rgba(0,0,0,0) !important;
	background: transparent !important;
}

.fcVbWrapper ul .videoWrapper {
	padding-top: 0px !important;
	margin-bottom: 15px !important;
}

/* Other */
.fc_img_container {
    background-size: cover;
    background-position: center center;
	width: 100%;	
}

.fcGridWrapper .bx-caption2,
.fcWrapper .bx-caption2 {
	background: #fff;
	width: 100%;
}

.fcGridWrapper .bx-caption2 span,
.fcWrapper .bx-caption2 span {
	color: inherit;
	display: block;
	font-size: 13px;
	padding: 8px 8px 0px 8px !important;
}

.fcGridWrapper .fcAuthor {
	display: block;
	padding: 3px 8px 8px 8px !important;	
}

.fcWrapper .fcAuthor {
	display: block;
	padding: 3px 8px 0px 8px !important;
}
